raw_first:
{
 "rules": [
  {
   "rule_id": "R-KBYY-S2-R04-01",
   "status": "OK",
   "label": "연령 만 19세 자동전환",
   "source": {
    "quote": "▪ 매년 첫 영업일에 가입자의 연령이 만 19세인 경우 「KB국민ONE통장」으로 자동전환"
   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "contract.reference_date",
       "offset_months": -12,
       "day": "first"
      },
      "to": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    "and": [
     {
      "==": [
       {
        "var": "customer.age"
       },
       19
      ]
     },
     {
      "exists": {
       "event": "PRODUCT_SWITCH",
       "within": {
        "ref": "$window"
       }
      }
     }
    ]
   },
   "effect": {
    "type": "REQUIRE",
    "value": "KB국민ONE통장"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R04-02",
   "status": "OK",
   "label": "KB종합통장 보유자 자동전환",
   "source": {
    "quote": "※ 단, KB국민ONE통장을 이미 보유하고 있는 경우에는 「KB종합통장」으로 자동전환"
   },
   "condition": {
    "==": [
     {
      "var": "customer.has_product"
     },
     "KB국민ONE통장"
    ]
   },
   "effect": {
    "type": "REQUIRE",
    "value": "KB종합통장"
   }
  }
 ]
}

